import React, { useState } from 'react';
import TimeBlock from './TimeBlock';

function DayPlanner({ date, entries, setEntries }) {
  const dateKey = date.toDateString();
  const dayEntry = entries[dateKey] || { morning: [], day: [], evening: [] };

  const timeBlocks = [
    { id: 'morning', title: '🌅 Утро', time: '06:00 - 12:00', icon: '☀️' },
    { id: 'day', title: '☀️ День', time: '12:00 - 18:00', icon: '🌤️' },
    { id: 'evening', title: '🌙 Вечер', time: '18:00 - 00:00', icon: '🌙' }
  ];

  const handleBlockUpdate = (blockId, items) => {
    setEntries({
      ...entries,
      [dateKey]: {
        ...dayEntry,
        [blockId]: items
      }
    });
  };

  return (
    <div className="day-planner">
      <h2>
        Планы на {date.toLocaleDateString('ru-RU', {
          weekday: 'long',
          year: 'numeric',
          month: 'long',
          day: 'numeric'
        })}
      </h2>

      <div className="time-blocks">
        {timeBlocks.map(block => (
          <TimeBlock
            key={block.id}
            id={block.id}
            title={block.title}
            time={block.time}
            icon={block.icon}
            items={dayEntry[block.id]}
            onUpdate={(items) => handleBlockUpdate(block.id, items)}
          />
        ))}
      </div>
    </div>
  );
}

export default DayPlanner;
